sys_ui_action.client_script_v2:
function onClick(g_form) {
    if (gs.getProperty("x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss")== current.trade_id.source_system) {
    if (current.swift_attribute_sync == 'Attribute Sync is in progress') {
        gs.addInfoMessage('Swift Attribute Sync is already in progress');
        action.setRedirectURL(current);
    } else {
        gs.eventQueue('x_hsb11_mss_c_proc.el_custody_swift_comp', current);
        current.swift_attribute_sync = 'Attribute Sync is in progress';
        current.update();
        action.setRedirectURL(current);
    }
} else {
    if (current.swift_attribute_sync == 'Attribute Sync is in progress') {
        gs.addInfoMessage('Swift Attribute Sync is already in progress');
        action.setRedirectURL(current);
    } else {
        gs.eventQueue('x_hsb11_mss_c_proc.el_custody_swift_reje', current);
        current.swift_attribute_sync = 'Attribute Sync is in progress';
        current.update();
        action.setRedirectURL(current);
    }
}
if (current.position_attribute_sync == 'Attribute Sync is in progress') {
    gs.addInfoMessage('Position Attribute Sync is already in progress');
    action.setRedirectURL(current);
} else {
    gs.eventQueue('x_hsb11_mss_c_proc.el_custody_detail_pos', current);
    current.position_attribute_sync = 'Attribute Sync is in progress';
    current.update();
    action.setRedirectURL(current);
}
}

sys_ui_action.script:
//  MSSOTIQUBE - 2406

var TradeSysId = current.trade_id;
var TaskSysId = current.sys_id;
var SwiftattributeSync = current.swift_attribute_sync;
var PosattributeSync = current.position_attribute_sync;

if (current.swift_attribute_sync == 'Attribute Sync is in progress') {
    gs.addInfoMessage('Swift Attribute Sync is already in progress');
    action.setRedirectURL(current);
} else {
    new x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils().refreshSwiftMessageAPICallTask(TradeSysId, SwiftattributeSync, TaskSysId);
    current.swift_attribute_sync = "Attribute Sync is in progress";
    current.update();
    action.setRedirectURL(current);
}


if (((gs.getProperty("x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss") == current.trade_id.source_system) || gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_gcs') == current.trade_id.source_system) && (gs.getProperty('x_hsb11_mss_pos.hsbcmss_el_custodyPositiononDemand_active') == 'true')) {

    if (current.position_attribute_sync == 'Attribute Sync is in progress') {

        gs.addInfoMessage('Position Attribute Sync is already in progress');
        action.setRedirectURL(current);
    } else {
        if (current.trade_id.securities_account == '' || current.trade_id.security_id == '') {

            gs.addErrorMessage('Holdings data sync was not completed due to missing security information.');
            //action.setRedirectURL(current);
        } else {

            new x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils().refreshPositionDataAPICallTask(TradeSysId, PosattributeSync, TaskSysId);
            current.position_attribute_sync = 'Attribute Sync is in progress';
            current.position_data_refresh_frequency_in_seconds = '';
            current.update();
            action.setRedirectURL(current);
        }
    }

}
